local function closestClue() local hrp=plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") if not hrp then return end local cl,md,pos=nil,1e9,nil for _,v in ipairs(workspace:GetDescendants()) do if v.Name=="DisguisedEggClue" then local p=getBase(v) if p then local d=(V3(hrp.Position.X,0,hrp.Position.Z)-V3(p.X,0,p.Z)).Magnitude if d<md then md=d cl=v pos=p end end end end return cl,pos end
local function closestBlood() local fo=workspace:FindFirstChild("BloodMoonPumpkinKings") if not fo then return end local hrp=plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") if not hrp then return end local cl,md,ps=nil,1e9,nil for _,v in ipairs(fo:GetDescendants()) do if v:IsA("Model") then local p=getBase(v) if p then local d=(V3(hrp.Position.X,0,hrp.Position.Z)-V3(p.X,0,p.Z)).Magnitude if d<md then md=d cl=v ps=p end end end end if not cl then local p=getBase(fo) return fo,p end return cl,ps end

