local function refreshPanel() if not listFrame then return end for _,v in ipairs(listFrame:GetChildren()) do if v:IsA("Frame") then v:Destroy() end end local fo=workspace:FindFirstChild("AnimalPickups") if not fo then return end local lst={} for _,m in ipairs(fo:GetChildren()) do if m:IsA("Model") then table.insert(lst,m) end end table.sort(lst,function(a,b) return (RScore[a:GetAttribute("Rarity") or ""] or 0)>(RScore[b:GetAttribute("Rarity") or ""] or 0) end) for _,m in ipairs(lst) do local rar=m:GetAttribute("Rarity") or "?" local f=Instance.new("Frame",listFrame) f.Size=UDim2.new(1,0,0,44) f.BackgroundColor3=Color3.fromRGB(24,22,36) Instance.new("UICorner",f).CornerRadius=UDim.new(0,10) Instance.new("UIStroke",f).Color=Color3.fromRGB(60,55,80) local lb=Instance.new("TextLabel",f) lb.Size=UDim2.new(1,-60,0,14) lb.Position=UDim2.new(0,8,0,4) lb.BackgroundTransparency=1 lb.Text=m.Name:upper().." • "..string.upper(rar) lb.Font=Enum.Font.GothamBold lb.TextSize=10 lb.TextColor3=C3(1,1,1) lb.TextXAlignment=Enum.TextXAlignment.Left local lb2=Instance.new("TextLabel",f) lb2.Size=UDim2.new(1,-60,0,10) lb2.Position=UDim2.new(0,8,0,20) lb2.BackgroundTransparency=1 lb2.Text=getZone(m).." • "..getCash(m) lb2.Font=Enum.Font.GothamMedium lb2.TextSize=8 lb2.TextColor3=DIM lb2.TextXAlignment=Enum.TextXAlignment.Left local btn=Instance.new("TextButton",f) btn.Size=UDim2.fromOffset(46,28) btn.Position=UDim2.new(1,-52,0.5,-14) btn.Text="STEAL" btn.Font=Enum.Font.GothamBold btn.TextSize=9 btn.TextColor3=C3(1,1,1) btn.BackgroundColor3=ACC Instance.new("UICorner",btn).CornerRadius=UDim.new(0,8) btn.MouseButton1Click:Connect(function() steal(m) end) end end

