local ord=1 MainAPI:Section("BASE") local baseT=mkToggle(mainF,ord,"Auto Base","Balik pas steal") ord+=1 MainAPI:Divider() MainAPI:Section("MOVEMENT") MainAPI:Slider({Title="Walk Speed",Flag="WalkSpeed",Min=16,Max=500,Step=1,Default=spd,Suffix=" SPD",Callback=function(v) spd=v local h=plr.Character and plr.Character:FindFirstChildOfClass("Humanoid") if h then h.WalkSpeed=v end end}) MainAPI:Divider() MainAPI:Section("STEAL") MainAPI:Dropdown({Title="Rarity",Flag="RarityF",Options=rarityNames2,Multi=true,Callback=function(v) sel={} if type(v)=="table" then for _,n in ipairs(v) do sel[n]=true end elseif v then sel[v]=true end end}) MainAPI:Dropdown({Title="Zone",Flag="ZoneF",Options=zoneNames,Multi=true,Callback=function(v) selZone={} if type(v)=="table" then for _,n in ipairs(v) do selZone[n]=true end elseif v then selZone[v]=true end end}) MainAPI:Dropdown({Title="Defend",Flag="DefendF",Options={"None","ZigZag","Random","Circle","Juke"},Default="None",Callback=function(v) defend=type(v)=="table" and v[1] or v end}) MainAPI:Textbox({Title="Min $/s",Flag="CashF",Placeholder="$0=off",Callback=function(t) minCash=parseCash(t) end}) MainAPI:Divider() local stealT=mkToggle(mainF,ord,"Auto Steal","Filter rarity") ord+=1 local atkT=mkToggle(mainF,ord,"Attack Carrier","Hajar") ord+=1 MainAPI:Divider() MainAPI:Section("PANEL NATIVE") local panelT=mkToggle(mainF,ord,"External Panel","Native Window:Panel") ord+=1 MainAPI:Divider() MainAPI:Section("EGG") MainAPI:Dropdown({Title="Egg Zone",Flag="EggZone",Options=zoneNames,Callback=function(v) selEggZone=type(v)=="table" and v[1] or v end}) local bigT=mkToggle(mainF,ord,"Big Egg Priority","Gede dulu") ord+=1 local eggT=mkToggle(mainF,ord,"Break Egg","Auto break") ord+=1

MiscAPI:Section("MISC") local ragT=mkToggle(miscF,1,"No Ragdoll","Anti ragdoll") local mentT=mkToggle(miscF,2,"Anti Mental","Anti fling") local fastT=mkToggle(miscF,3,"Fast Break","Bypass swing")
EspAPI:Section("ESP") local espAcc=EspAPI:Accordion({Title="ESP ANIMAL",Open=true}) espAcc:Dropdown({Title="Rarity ESP",Flag="EspRar",Options=rarityNames2,Multi=true,Callback=function(v) selEsp={} if type(v)=="table" then for _,n in ipairs(v) do selEsp[n]=true end elseif v then selEsp[v]=true end if espOn then refreshEsp() end end}) local espT=mkToggle(espF,1,"Animal ESP","Highlight") local espClearT=mkToggle(espF,2,"Clear On Death","Auto clear") tw(espClearT.track,{BackgroundColor3=ACC},.2):Play() tw(espClearT.dot,{Position=UDim2.new(1,-21,0.5,-9)},.2):Play()
AnimalAPI:Section("PET") local aAcc=AnimalAPI:Accordion({Title="Auto Best Animal",Open=true}) aAcc:Label("EquipBest loop 1s") local bestT=mkToggle(animalF,1,"Auto Best Animal","Loop EquipBest")
EventAPI:Section("EVENT") local eAcc=EventAPI:Accordion({Title="Auto Halloween",Open=true}) eAcc:Slider({Title="Stay Duration",Flag="HallStay",Min=1,Max=15,Step=.5,Default=3,Suffix="s",Callback=function(v) hallStay=v end}) local hallT=mkToggle(eventF,1,"Auto Halloween","DisguisedEggClue + reset") local bloodAcc=EventAPI:Accordion({Title="Auto BloodMoon",Open=true}) bloodAcc:Label("BloodMoonPumpkinKings reset+break") local bloodT=mkToggle(eventF,2,"Auto BloodMoon","Reset + break terdekat")

-- LOGIC
local function getTargets() local fo=workspace:FindFirstChild("AnimalPickups") if not fo or next(sel)==nil then return {} end local out={} for _,m in ipairs(fo:GetChildren()) do if m:IsA("Model") and sel[m:GetAttribute("Rarity")] then if next(selZone)~=nil and not selZone[getZone(m)] then continue end if minCash>0 and parseCash(getCash(m))<minCash then continue end table.insert(out,m) end end table.sort(out,function(a,b) return (RScore[a:GetAttribute("Rarity") or ""] or 0)>(RScore[b:GetAttribute("Rarity") or ""] or 0) end) return out end
local baseOn,baseConn=false,nil baseT.btn.MouseButton1Click:Connect(function() baseOn=not baseOn if baseOn then tw(baseT.track,{BackgroundColor3=ACC},.2):Play() tw(baseT.dot,{Position=UDim2.new(1,-21,0.5,-9)},.2):Play() baseConn=PPS.PromptTriggered:Connect(function(pr,p) if p==plr and pr.Name:lower():find("steal") then task.wait(.2) walkBase() end end) else tw(baseT.track,{BackgroundColor3=Color3.fromRGB(34,30,50)},.2):Play() tw(baseT.dot,{Position=UDim2.new(0,3,0.5,-9)},.2):Play() if baseConn then baseConn:Disconnect() end end end)
local stealOn=false stealT.btn.MouseButton1Click:Connect(function() stealOn=not stealOn if stealOn then if next(sel)==nil then stealOn=false Window.Notify("ERR","Pilih rarity",Color3.fromRGB(248,113,113),2) return end tw(stealT.track,{BackgroundColor3=ACC},.2):Play() tw(stealT.dot,{Position=UDim2.new(1,-21,0.5,-9)},.2):Play() task.spawn(function() while stealOn do if hallAct or bloodAct then task.wait(.5) continue end local lst=getTargets() if #lst==0 then task.wait(.8) continue end for _,m in ipairs(lst) do if not stealOn or hallAct or bloodAct then break end pcall(steal,m) task.wait(.4) end end end) else tw(stealT.track,{BackgroundColor3=Color3.fromRGB(34,30,50)},.2):Play() tw(stealT.dot,{Position=UDim2.new(0,3,0.5,-9)},.2):Play() end end)
atkT.btn.MouseButton1Click:Connect(function() atk=not atk if atk then tw(atkT.track,{BackgroundColor3=Color3.fromRGB(255,80,80)},.2):Play() tw(atkT.dot,{Position=UDim2.new(1,-21,0.5,-9)},.2):Play() else tw(atkT.track,{BackgroundColor3=Color3.fromRGB(34,30,50)},.2):Play() tw(atkT.dot,{Position=UDim2.new(0,3,0.5,-9)},.2):Play() end attackEnabled=atk end)
local extOn=false panelT.btn.MouseButton1Click:Connect(function() extOn=not extOn if extOn then tw(panelT.track,{BackgroundColor3=ACC},.2):Play() tw(panelT.dot,{Position=UDim2.new(1,-21,0.5,-9)},.2):Play() StealPanel:Show() refreshPanel() task.spawn(function() while extOn and StealPanel:IsOpen() do refreshPanel() task.wait(2) end end) else tw(panelT.track,{BackgroundColor3=Color3.fromRGB(34,30,50)},.2):Play() tw(panelT.dot,{Position=UDim2.new(0,3,0.5,-9)},.2):Play() StealPanel:Hide() end end)
local function getEggSize(m) for _,a in ipairs({"Size","EggSize","Scale"}) do local v=m:GetAttribute(a) if type(v)=="number" then return v end end local ok,_,s=pcall(function() return m:GetBoundingBox() end) if ok and s then return s.Magnitude end return 0 end
local function getEggs(zone) local zb=getZoneFolder() if not zb then return {} end local zm=zb:FindFirstChild(zone) if not zm then return {} end local er=zm:FindFirstChild("Eggs") or zm local out={} for _,v in ipairs(er:GetChildren()) do if v:IsA("Model") and v.Name:lower():find("egg") then table.insert(out,v) end end if bigEgg then table.sort(out,function(a,b) return getEggSize(a)>getEggSize(b) end) end return out end
local function getEggHealth(m) return m:GetAttribute("Health") end
local function equipPick() local ch=plr.Character if not ch then return end local t=ch:FindFirstChildOfClass("Tool") if t and t.Name:lower():find("pick") then return t end for _,v in ipairs(plr.Backpack:GetChildren()) do if v:IsA("Tool") then v.Parent=ch return v end end end
bigT.btn.MouseButton1Click:Connect(function() bigEgg=not bigEgg if bigEgg then tw(bigT.track,{BackgroundColor3=ACC},.2):Play() tw(bigT.dot,{Position=UDim2.new(1,-21,0.5,-9)},.2):Play() else tw(bigT.track,{BackgroundColor3=Color3.fromRGB(34,30,50)},.2):Play() tw(bigT.dot,{Position=UDim2.new(0,3,0.5,-9)},.2):Play() end end) tw(bigT.track,{BackgroundColor3=ACC},.2):Play() tw(bigT.dot,{Position=UDim2.new(1,-21,0.5,-9)},.2):Play()
local breakOn=false eggT.btn.MouseButton1Click:Connect(function() breakOn=not breakOn if breakOn then if not selEggZone then breakOn=false Window.Notify("ERR","Pilih zone",Color3.fromRGB(248,113,113),2) return end tw(eggT.track,{BackgroundColor3=Color3.fromRGB(255,220,90)},.2):Play() tw(eggT.dot,{Position=UDim2.new(1,-21,0.5,-9)},.2):Play() task.spawn(function() while breakOn do if hallAct or bloodAct then task.wait(.5) continue end if #getTargets()>0 then for _,m in ipairs(getTargets()) do if not breakOn or hallAct or bloodAct then break end pcall(steal,m) task.wait(.3) end continue end local eggs=getEggs(selEggZone) if #eggs==0 then task.wait(1) continue end for _,eg in ipairs(eggs) do if not breakOn or hallAct or bloodAct then break end if #getTargets()>0 then break end local p,b=getOff(eg) if not p then local bp=getBase(eg) if bp then p=V3(bp.X,3.5,bp.Z+3) b=V3(bp.X,3.5,bp.Z) end end if not p then continue end pcall(function() walkTo(p,b) equipPick() while breakOn and eg.Parent and not hallAct and not bloodAct do if #getTargets()>0 then break end local h=getEggHealth(eg) if h and h<=0 then break end task.wait(.15) end end) task.wait(.2) end end end) else tw(eggT.track,{BackgroundColor3=Color3.fromRGB(34,30,50)},.2):Play() tw(eggT.dot,{Position=UDim2.new(0,3,0.5,-9)},.2):Play() end end)

-- AUTO BEST
local bestOn=false bestT.btn.MouseButton1Click:Connect(function() bestOn=not bestOn if bestOn then tw(bestT.track,{BackgroundColor3=ACC},.2):Play() tw(bestT.dot,{Position=UDim2.new(1,-21,0.5,-9)},.2):Play() task.spawn(function() while bestOn do pcall(function() RS.PetsInventoryRemote:FireServer("EquipBest") end) task.wait(1) end end) else tw(bestT.track,{BackgroundColor3=Color3.fromRGB(34,30,50)},.2):Play() tw(bestT.dot,{Position=UDim2.new(0,3,0.5,-9)},.2):Play() end end)
espT.btn.MouseButton1Click:Connect(function() espOn=not espOn if espOn then tw(espT.track,{BackgroundColor3=ACC},.2):Play() tw(espT.dot,{Position=UDim2.new(1,-21,0.5,-9)},.2):Play() refreshEsp() task.spawn(function() while espOn do refreshEsp() task.wait(1.5) end end) else tw(espT.track,{BackgroundColor3=Color3.fromRGB(34,30,50)},.2):Play() tw(espT.dot,{Position=UDim2.new(0,3,0.5,-9)},.2):Play() clearEsp() end end)

-- EVENT HALLOWEEN + BLOODMOON ANALYSIS
local function resetChar() pcall(function() local h=plr.Character and plr.Character:FindFirstChildOfClass("Humanoid") if h then h.Health=0 else plr.Character:BreakJoints() end end) end
hallT.btn.MouseButton1Click:Connect(function() hallOn=not hallOn if hallOn then tw(hallT.track,{BackgroundColor3=Color3.fromRGB(255,140,0)},.2):Play() tw(hallT.dot,{Position=UDim2.new(1,-21,0.5,-9)},.2):Play() Window.Notify("HALLOWEEN","ON",Color3.fromRGB(255,140,0),2) task.spawn(function() while hallOn do local cl,pos=closestClue() if cl and pos then lastClue=tick() if not hallAct then hallAct=true hasResetHall=false Window.Notify("EVENT","Clue muncul! Reset 1x",ACC,2) end if not hasResetHall then hasResetHall=true resetChar() task.wait(2) continue end walkTo(V3(pos.X,3.5,pos.Z),pos) task.wait(hallStay) else if hallAct and tick()-lastClue>10 then hallAct=false hasResetHall=false Window.Notify("EVENT","Clue end 10s -> break egg lanjut",DIM,2) end task.wait(.5) end end end) else tw(hallT.track,{BackgroundColor3=Color3.fromRGB(34,30,50)},.2):Play() tw(hallT.dot,{Position=UDim2.new(0,3,0.5,-9)},.2):Play() hallAct=false end end)
bloodT.btn.MouseButton1Click:Connect(function() bloodOn=not bloodOn if bloodOn then tw(bloodT.track,{BackgroundColor3=Color3.fromRGB(180,0,0)},.2):Play() tw(bloodT.dot,{Position=UDim2.new(1,-21,0.5,-9)},.2):Play() Window.Notify("BLOODMOON","ON",Color3.fromRGB(180,0,0),2) task.spawn(function() while bloodOn do local tgt,pos=closestBlood() if tgt and pos then lastBlood=tick() if not bloodAct then bloodAct=true hasResetBlood=false Window.Notify("BLOOD","PumpkinKings muncul! Reset",Color3.fromRGB(180,0,0),2) end if not hasResetBlood then hasResetBlood=true resetChar() task.wait(2) continue end walkTo(V3(pos.X,3.5,pos.Z),pos) equipPick() local st=tick() while bloodOn and tgt.Parent and tick()-st<12 do local h=getEggHealth(tgt) if h and h<=0 then break end task.wait(.2) end else if bloodAct and tick()-lastBlood>10 then bloodAct=false hasResetBlood=false Window.Notify("BLOOD","End 10s -> lanjut",DIM,2) end task.wait(.5) end end end) else tw(bloodT.track,{BackgroundColor3=Color3.fromRGB(34,30,50)},.2):Play() tw(bloodT.dot,{Position=UDim2.new(0,3,0.5,-9)},.2):Play() bloodAct=false end end)

-- MISC
local noRagOn,ragConns=false,{} local function enRag() for _,c in ipairs(ragConns) do pcall(function() c:Disconnect() end) end ragConns={} local h=plr.Character and plr.Character:FindFirstChildOfClass("Humanoid") if h then pcall(function() h:SetStateEnabled(Enum.HumanoidStateType.Ragdoll,false) h:SetStateEnabled(Enum.HumanoidStateType.FallingDown,false) end) table.insert(ragConns,h.StateChanged:Connect(function(_,n) if n==Enum.HumanoidStateType.Ragdoll or n==Enum.HumanoidStateType.FallingDown then h:ChangeState(Enum.HumanoidStateType.GettingUp) end end)) end end ragT.btn.MouseButton1Click:Connect(function() noRagOn=not noRagOn if noRagOn then tw(ragT.track,{BackgroundColor3=ACC},.2):Play() tw(ragT.dot,{Position=UDim2.new(1,-21,0.5,-9)},.2):Play() enRag() else tw(ragT.track,{BackgroundColor3=Color3.fromRGB(34,30,50)},.2):Play() tw(ragT.dot,{Position=UDim2.new(0,3,0.5,-9)},.2):Play() end end)
local antiOn,antiConns=false,{} antiOn=false mentT.btn.MouseButton1Click:Connect(function() antiOn=not antiOn if antiOn then tw(mentT.track,{BackgroundColor3=ACC},.2):Play() tw(mentT.dot,{Position=UDim2.new(1,-21,0.5,-9)},.2):Play() antiConns={} table.insert(antiConns,RunS.Heartbeat:Connect(function() local hrp=plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") if not hrp then return end if hrp.AssemblyLinearVelocity.Magnitude>35 then hrp.AssemblyLinearVelocity=V3(0,hrp.AssemblyLinearVelocity.Y,0) hrp.AssemblyAngularVelocity=Vector3.zero end end)) else tw(mentT.track,{BackgroundColor3=Color3.fromRGB(34,30,50)},.2):Play() tw(mentT.dot,{Position=UDim2.new(0,3,0.5,-9)},.2):Play() for _,c in ipairs(antiConns) do pcall(function() c:Disconnect() end) end end end)
local fastOn,fastConn=false,nil fastT.btn.MouseButton1Click:Connect(function() fastOn=not fastOn if fastOn then tw(fastT.track,{BackgroundColor3=ACC},.2):Play() tw(fastT.dot,{Position=UDim2.new(1,-21,0.5,-9)},.2):Play() fastConn=RunS.Heartbeat:Connect(function() pcall(function() plr:SetAttribute("FastSwingOwned",true) end) end) else tw(fastT.track,{BackgroundColor3=Color3.fromRGB(34,30,50)},.2):Play() tw(fastT.dot,{Position=UDim2.new(0,3,0.5,-9)},.2):Play() if fastConn then fastConn:Disconnect() end end end)

plr.CharacterAdded:Connect(function(c) task.wait(.5) local h=c:WaitForChild("Humanoid",10) if h then spd=h.WalkSpeed end if espOn then task.wait(.5) refreshEsp() end end)
RunS.Heartbeat:Connect(function() local h=plr.Character and plr.Character:FindFirstChildOfClass("Humanoid") if h and math.abs(h.WalkSpeed-spd)>.1 then h.WalkSpeed=spd end end)
